bounded_host_request.command:
set -euo pipefail
root="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
cd "$root"
test "$(systemctl --user is-active gace-userbot-verify.service)" = active
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true
test -S "$root/deploy/secrets/userbot_verify.sock"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
gh api repos/seigo-gace/GateApp-Bot/tarball/fac6bfd5b1ec38809368d3a3097001d0080eace7 > "$tmp/source.tar.gz"
tar -xzf "$tmp/source.tar.gz" -C "$tmp" --strip-components=1
python3 -B - "$tmp" "$root" <<'PY'
import sys,json,subprocess,os,pathlib,asyncio
tmp,root=map(pathlib.Path,sys.argv[1:])
sys.path.insert(0,str(tmp/"scripts"))
import publish_missing_normal_topic_buttons as existing
import userbot_topic_audit_client as audit
audit.SOCKET_PATH=root/"deploy/secrets/userbot_verify.sock"
groups={"area":-1003847210571,"video":-1002373696859,"category":-1003770334893}
notice="📢 <b>プロフィール機能の改善のお知らせ</b>\n\nプロフィールの変更ができないなどの不具合について、改善を行いました。\n\n✅ 登録済みプロフィールの編集・保存処理を改善\n✅ 髪型・体型・エリアの変更ボタンを修正\n✅ 編集中の入力内容が保持されるよう改善\n✅ 他の機能と入力が混同される不具合を修正\n\n<b>変更方法</b>\n投稿メニューの「プロフ作成」から、登録済みのプロフィールを開いて変更してください。\n\n引き続き不具合がある場合は、投稿メニューの「🐞 不具合を報告」からお知らせください。\n\nご不便をおかけして申し訳ございません。ご報告いただいた皆さま、ありがとうございます。"
targets=[]
for group,chat in groups.items():
    try:
        data=asyncio.run(audit.inspect(chat,-1))
        rows=data["rows"]
        found=[v for v in rows if v.get("topic_id")==1 and "お知らせ" in str(v.get("title",""))]
        if len(found)==1:
            targets.append((group,chat,1))
            continue
        data=asyncio.run(audit.inspect(chat,0))
        matches=[int(v["topic_id"]) for v in data["rows"] if "お知らせ" in str(v.get("title","")) and str(v.get("title","")).lstrip().startswith(("0","０","⓪","🆕"))]
        if len(matches)==1:
            targets.append((group,chat,matches[0]))
        else:
            print("NOTICE_TOPIC_NOT_VERIFIED="+group)
    except Exception as e:
        print("NOTICE_TOPIC_AUDIT_FAILED="+group+":"+type(e).__name__)
if not targets: raise SystemExit(3)
js=existing.BOT_NODE.split("(async()=>{",1)[0].replace("__TASK_JSON__",json.dumps({"targets":targets,"text":notice},ensure_ascii=False))+"""
(async()=>{
 const me=await api('getMe',{});
 if(!me.ok||String(me.value?.username||'').toLowerCase()!=='gaybbs_bot')throw Error('BOT_IDENTITY_INVALID');
 let failures=0;
 for(const [group,chat,thread] of task.targets){
  try{
   const membership=await api('getChatMember',{chat_id:chat,user_id:me.value.id});
   if(!membership.ok||!['administrator','creator'].includes(membership.value?.status)){
     console.log(JSON.stringify({group,state:'NOT_ADMIN'}));failures++;continue;
   }
   const r=await api('sendMessage',{chat_id:chat,...(thread===1?{}:{message_thread_id:thread}),text:task.text,parse_mode:'HTML',link_preview_options:{is_disabled:true}});
   const m=r.value;
   if(!r.ok){console.log(JSON.stringify({group,state:'DENIED',code:r.code}));failures++;continue;}
   if(m?.chat?.id!==chat||!Number.isSafeInteger(m.message_id)||(thread!==1&&m.message_thread_id!==thread)){console.log(JSON.stringify({group,state:'UNCERTAIN'}));failures++;continue;}
   console.log(JSON.stringify({group,state:'PUBLISHED',thread_id:thread,message_id:m.message_id}));
  }catch{console.log(JSON.stringify({group,state:'UNCERTAIN'}));failures++;}
 }
 if(failures)process.exitCode=2;
})().catch(()=>{console.log(JSON.stringify({state:'IDENTITY_OR_TRANSPORT_FAILED'}));process.exitCode=3;});
"""
ledger=root/"deploy/state/profile-improvement-notice-20261127.json"
ledger.parent.mkdir(parents=True,exist_ok=True)
fd=os.open(ledger,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
with os.fdopen(fd,"w") as f:
    json.dump({"state":"attempt_started","targets":targets},f);f.flush();os.fsync(f.fileno())
p=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","-"],input=js,text=True,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=180)
results=[json.loads(x) for x in p.stdout.splitlines() if x.startswith("{")]
with ledger.open("w") as f:
    json.dump({"state":"finished","targets":targets,"results":results,"exit_code":p.returncode},f);f.flush();os.fsync(f.fileno())
for r in results: print(json.dumps(r,ensure_ascii=False))
print("NOTICE_TARGETS_VERIFIED="+str(len(targets)))
print("NOTICE_PUBLISHED_COUNT="+str(sum(r.get("state")=="PUBLISHED" for r in results)))
raise SystemExit(0 if p.returncode==0 and len(results)==len(targets)==3 and all(r.get("state")=="PUBLISHED" for r in results) else 2)
PY
test "$(systemctl --user is-active gace-userbot-verify.service)" = active
